/**
 * The excerpt-context policy's measurement corpus (Task 16e; gate G6, the 16d verdict's
 * finding 1): 200 whole sentences of real NTSB passages, drawn at random (seed 1605) from
 * the development evidence (evidence.json, evidence-16d.json) by section (60 probable-cause,
 * 70 analysis, 70 factual sentences of at least five words; headings-only lines and every
 * sentence that a calibration quote uses were left out), each labelled `standalone` or
 * `needs_context` before `excerpt-context-v1` was run on them. A sentence needs context when
 * read alone, in a card about its case, it does not say what a reference points to (a
 * pronoun, a demonstrative, a relative time or sequence, a comparison with no object, a
 * connective that continues earlier text), when it is a fragment, or when it omits the
 * setting it describes (a test run that reads as a flight). A definite description of a
 * part or party of the case ("the engine", "the fitting", "the mechanic") names it through
 * the case; a generic one that points back ("the area", "the tests") does not. Labels are
 * the author's (model-reviewed), not expert ground truth.
 */
export interface ExcerptSentence {
  id: string;
  ntsbNo: string;
  /** The canonical passage id (evidence files). */
  passageId: string;
  section: 'factual' | 'analysis' | 'probable_cause';
  label: 'standalone' | 'needs_context';
  reason?: string;
  text: string;
}

